IMAGES = {
    "dirt":    "",
    "creeper": "",
    "ender":   "",
    "diamond": "",
    "nether":  "",
}

_pixmap_cache = {}

def get_pixmap(theme_key):
    if theme_key not in _pixmap_cache:
        data = base64.b64decode(IMAGES[theme_key])
        pix = QPixmap()
        pix.loadFromData(data)
        _pixmap_cache[theme_key] = pix
    return _pixmap_cache[theme_key]


