class SignalBus(QObject):
    status = Signal(str)
    progress = Signal(int)
    maximum = Signal(int)
    versions_loaded = Signal(list)
    refresh_requested = Signal()
    show_error = Signal(str, str)
    show_warning = Signal(str, str)
    show_info = Signal(str, str)
    game_closed = Signal()
    install_done = Signal()
    loader_done = Signal()
    loader_success = Signal()
    modpack_done = Signal()
    modpack_created = Signal()


