# =========================================================
# BACKGROUND WIDGET (dirt texture + overlay)
# =========================================================

class BackgroundWidget(QWidget):

    def __init__(self):
        super().__init__()
        self._pixmap = None
        self._overlay = QColor(0, 0, 0, 170)

    def set_theme(self, t):
        self._pixmap = get_pixmap(current_theme)
        self._overlay = QColor(t["overlay"])
        self._overlay.setAlpha(t["overlay_alpha"])
        self.update()

    def paintEvent(self, event):
        painter = QPainter(self)
        if self._pixmap is not None:
            pix = self._pixmap.scaled(
                self.size(),
                Qt.KeepAspectRatioByExpanding,
                Qt.FastTransformation
            )
            x = (self.width() - pix.width()) // 2
            y = (self.height() - pix.height()) // 2
            painter.drawPixmap(x, y, pix)
        painter.fillRect(self.rect(), self._overlay)
        painter.end()


