# =========================================================

class SetupDialog(QDialog):

    def __init__(self, main_window, first_run=False):
        super().__init__(main_window)
        self.main = main_window
        self.first_run = first_run

        self.setWindowTitle(tr("title_setup"))
        self.setFixedSize(540, 640)
        self.setModal(True)

        layout = QVBoxLayout(self)
        layout.setContentsMargins(40, 30, 40, 26)
        layout.setSpacing(6)

        title = QLabel(tr("title_setup"))
        title.setObjectName("dialogTitle")
        title.setAlignment(Qt.AlignCenter)
        layout.addWidget(title)

        subtitle = QLabel(tr("first_setup"))
        subtitle.setObjectName("mutedLabel")
        subtitle.setAlignment(Qt.AlignCenter)
        layout.addWidget(subtitle)
        layout.addSpacing(20)

        # Language
        layout.addWidget(self._label(tr("language")))
        self.lang_combo = QComboBox()
        self.lang_combo.addItem("English", "en")
        self.lang_combo.addItem("العربية", "ar")
        self.lang_combo.setCurrentIndex(
            0 if current_language == "en" else 1
        )
        layout.addWidget(self.lang_combo)

        layout.addSpacing(14)

        # Directory
        layout.addWidget(self._label(tr("directory")))
        dir_row = QHBoxLayout()
        dir_row.setSpacing(8)

        default_dir = (
            minecraft_directory
            or minecraft_launcher_lib.utils
            .get_minecraft_directory()
        )
        self.directory_edit = QLineEdit(default_dir)
        dir_row.addWidget(self.directory_edit, 1)

        browse_btn = QPushButton(tr("browse"))
        browse_btn.clicked.connect(self._browse)
        dir_row.addWidget(browse_btn)
        layout.addLayout(dir_row)

        layout.addSpacing(14)

        # Username
        layout.addWidget(self._label(tr("username")))
        self.username_edit = QLineEdit(player_name)
        self.username_edit.setPlaceholderText("Steve")
        layout.addWidget(self.username_edit)

        layout.addSpacing(14)

        # RAM
        layout.addWidget(self._label(tr("ram").replace(":", "")))
        self.ram_combo = QComboBox()
        self.ram_combo.addItems([
            "2 GB", "3 GB", "4 GB",
            "6 GB", "8 GB", "12 GB", "16 GB"
        ])
        self.ram_combo.setCurrentText(f"{ram_value} GB")
        layout.addWidget(self.ram_combo)

        layout.addStretch(1)

        save_btn = QPushButton(tr("save"))
        save_btn.setObjectName("saveButton")
        save_btn.clicked.connect(self._save)
        layout.addWidget(save_btn, alignment=Qt.AlignCenter)

    @staticmethod
    def _label(text):
        lbl = QLabel(text)
        lbl.setObjectName("sectionLabel")
        return lbl

    def _browse(self):
        directory = QFileDialog.getExistingDirectory(
            self, tr("directory"), self.directory_edit.text()
        )
        if directory:
            self.directory_edit.setText(directory)

    def _save(self):
        global minecraft_directory, player_name, ram_value

        directory = self.directory_edit.text().strip()
        username = self.username_edit.text().strip()
        ram = self.ram_combo.currentText().replace(" GB", "")
        lang = self.lang_combo.currentData()

        if not directory:
            QMessageBox.warning(
                self, tr("title_setup"), tr("warn_select_dir")
            )
            return
        if not username:
            QMessageBox.warning(
                self, tr("title_setup"), tr("warn_enter_username")
            )
            return

        minecraft_directory = directory
        player_name = username
        ram_value = ram

        os.makedirs(minecraft_directory, exist_ok=True)
        save_settings(
            minecraft_directory, player_name, ram_value, lang
        )
        save_directory_location(minecraft_directory)

        self.main.apply_language(lang, save=False)
        self.accept()


