class ThemeDialog(QDialog):

    def __init__(self, main_window):
        super().__init__(main_window)
        self.main = main_window

        self.setWindowTitle(tr("theme_title"))
        self.setFixedSize(480, 560)
        self.setModal(True)

        layout = QVBoxLayout(self)
        layout.setContentsMargins(32, 26, 32, 22)
        layout.setSpacing(8)

        title = QLabel("🎨  " + tr("theme_title"))
        title.setObjectName("dialogTitle")
        title.setAlignment(Qt.AlignCenter)
        layout.addWidget(title)
        layout.addSpacing(40)

        # Language buttons
        layout.addWidget(SetupDialog._label(tr("language")))
        lang_row = QHBoxLayout()
        lang_row.setSpacing(10)

        self.lang_buttons = {}
        for label, code in (("English", "en"), ("العربية", "ar")):
            btn = QPushButton(label)
            btn.setObjectName("actionButton")
            btn.clicked.connect(
                lambda _, c=code: self._set_language(c)
            )
            self.lang_buttons[code] = btn
            lang_row.addWidget(btn, 1)

        layout.addLayout(lang_row)
        layout.addSpacing(20)

        # Theme grid
        layout.addWidget(SetupDialog._label(tr("theme")))
        grid = QGridLayout()
        grid.setSpacing(10)

        self.theme_buttons = {}
        row, col = 0, 0
        for key, theme in THEMES.items():
            btn = QPushButton(theme["name"][current_language])
            btn.setCursor(Qt.PointingHandCursor)
            btn.clicked.connect(
                lambda _, k=key: self._set_theme(k)
            )
            self.theme_buttons[key] = btn
            grid.addWidget(btn, row, col)
            col += 1
            if col > 1:
                col = 0
                row += 1

        layout.addLayout(grid)
        layout.addStretch(1)

        close_btn = QPushButton(tr("close"))
        close_btn.setObjectName("actionButton")
        close_btn.clicked.connect(self.accept)
        layout.addWidget(close_btn)

        self._refresh_styles()

    def _set_language(self, code):
        self.main.apply_language(code)
        self._refresh_styles()
        self.setWindowTitle(tr("theme_title"))
        self.theme_label_refresh()

    def _set_theme(self, key):
        self.main.apply_theme(key)
        self._refresh_styles()

    def theme_label_refresh(self):
        # called after language switch
        self._refresh_styles()

    def _refresh_styles(self):
        t = THEMES[current_theme]
        for code, btn in self.lang_buttons.items():
            active = code == current_language
            btn.setStyleSheet(
                f"background-color: {t['accent'] if active else t['card2']};"
                f"color: #FFFFFF; border: 1px solid {t['accent']};"
                f"border-radius: 11px; padding: 10px; font-weight: 700;"
            )
        for key, btn in self.theme_buttons.items():
            th = THEMES[key]
            active = key == current_theme
            btn.setText(th["name"][current_language])
            btn.setStyleSheet(
                f"background-color: {th['accent'] if active else th['card2']};"
                f"color: #FFFFFF; border: 2px solid {th['accent']};"
                f"border-radius: 12px; padding: 16px 10px; font-weight: 800;"
            )


