class LoaderInstallerDialog(QDialog):

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowTitle(tr("setup_loader_title"))
        self.setFixedSize(470, 440)
        self.setModal(False)

        layout = QVBoxLayout(self)
        layout.setContentsMargins(40, 30, 40, 26)
        layout.setSpacing(6)

        title = QLabel(tr("setup_loader_title"))
        title.setObjectName("dialogTitle")
        title.setAlignment(Qt.AlignCenter)
        layout.addWidget(title)
        layout.addSpacing(20)

        layout.addWidget(SetupDialog._label(tr("mc_version")))
        self.mc_combo = QComboBox()
        self.mc_combo.addItems(get_release_versions())
        layout.addWidget(self.mc_combo)

        layout.addSpacing(16)
        layout.addWidget(SetupDialog._label(tr("loader")))
        self.loader_combo = QComboBox()
        self.loader_combo.addItems(["Fabric", "Forge"])
        layout.addWidget(self.loader_combo)

        layout.addStretch(1)

        self.install_btn = QPushButton(tr("install"))
        self.install_btn.setObjectName("installButton")
        self.install_btn.clicked.connect(self._install)
        layout.addWidget(self.install_btn, alignment=Qt.AlignCenter)

        bus.loader_done.connect(
            lambda: self.install_btn.setEnabled(True),
            Qt.QueuedConnection
        )
        bus.loader_success.connect(
            self.accept, Qt.QueuedConnection
        )

    def _install(self):
        mc_version = self.mc_combo.currentText()
        loader_name = self.loader_combo.currentText().lower()

        if not mc_version:
            QMessageBox.warning(
                self, tr("title_minecraft"), tr("warn_select_mc")
            )
            return

        self.install_btn.setEnabled(False)

        def worker():
            try:
                bus.status.emit(tr(
                    "installing_loader", l=loader_name, v=mc_version
                ))
                installed_id = install_mod_loader(
                    loader_name, mc_version
                )
                bus.status.emit(tr("installed_x", id=installed_id))
                bus.refresh_requested.emit()
                bus.loader_success.emit()
            except Exception as error:
                bus.show_error.emit(
                    tr("title_loader_error"), str(error)
                )
            finally:
                bus.loader_done.emit()

        threading.Thread(target=worker, daemon=True).start()


