class ModpackCreatorDialog(QDialog):

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowTitle(tr("modpack_title"))
        self.setFixedSize(500, 580)
        self.setModal(False)

        layout = QVBoxLayout(self)
        layout.setContentsMargins(40, 28, 40, 24)
        layout.setSpacing(6)

        title = QLabel(tr("modpack_title"))
        title.setObjectName("dialogTitle")
        title.setAlignment(Qt.AlignCenter)
        layout.addWidget(title)
        layout.addSpacing(18)

        layout.addWidget(SetupDialog._label(tr("modpack_name")))
        self.name_edit = QLineEdit()
        self.name_edit.setPlaceholderText("My Modpack")
        layout.addWidget(self.name_edit)

        layout.addSpacing(14)
        layout.addWidget(SetupDialog._label(tr("mc_version")))
        self.mc_combo = QComboBox()
        self.mc_combo.addItems(get_release_versions())
        layout.addWidget(self.mc_combo)

        layout.addSpacing(14)
        layout.addWidget(SetupDialog._label(tr("loader")))
        self.loader_combo = QComboBox()
        self.loader_combo.addItems([
            "Vanilla", "Fabric", "Forge"
        ])
        layout.addWidget(self.loader_combo)

        layout.addSpacing(14)
        layout.addWidget(SetupDialog._label("RAM"))
        self.ram_combo = QComboBox()
        self.ram_combo.addItems([
            "2 GB", "3 GB", "4 GB",
            "6 GB", "8 GB", "12 GB", "16 GB"
        ])
        self.ram_combo.setCurrentText(f"{ram_value} GB")
        layout.addWidget(self.ram_combo)

        layout.addStretch(1)

        self.create_btn = QPushButton(tr("create"))
        self.create_btn.setObjectName("installButton")
        self.create_btn.clicked.connect(self._create)
        layout.addWidget(self.create_btn, alignment=Qt.AlignCenter)

        bus.modpack_done.connect(
            lambda: self.create_btn.setEnabled(True),
            Qt.QueuedConnection
        )
        bus.modpack_created.connect(
            self.accept, Qt.QueuedConnection
        )

    def _create(self):
        name = self.name_edit.text().strip()
        mc_version = self.mc_combo.currentText()
        loader = self.loader_combo.currentText().lower()
        ram = self.ram_combo.currentText().replace(" GB", "")

        if not name:
            QMessageBox.warning(
                self, tr("modpack_title"), tr("warn_enter_name")
            )
            return

        safe_name = "".join(
            c for c in name if c.isalnum() or c in " _-"
        ).strip()

        if not safe_name:
            QMessageBox.critical(
                self, tr("modpack_title"), tr("err_invalid_name")
            )
            return

        instance_directory = os.path.join(
            get_modpacks_directory(), safe_name
        )

        if os.path.exists(instance_directory):
            QMessageBox.critical(
                self, tr("modpack_title"), tr("err_exists")
            )
            return

        self.create_btn.setEnabled(False)

        def worker():
            try:
                for sub in (
                    "mods", "config", "resourcepacks",
                    "shaderpacks", "saves"
                ):
                    os.makedirs(
                        os.path.join(instance_directory, sub)
                    )

                if loader == "vanilla":
                    launch_id = install_vanilla(mc_version)
                else:
                    launch_id = install_mod_loader(
                        loader, mc_version
                    )

                instance_data = {
                    "name": name,
                    "minecraft_version": mc_version,
                    "loader": loader,
                    "launch_id": launch_id,
                    "ram": ram,
                }

                with open(
                    os.path.join(
                        instance_directory, "instance.json"
                    ),
                    "w", encoding="utf-8"
                ) as file:
                    json.dump(instance_data, file, indent=4)

                bus.status.emit(tr("created_modpack", n=name))
                bus.refresh_requested.emit()
                bus.modpack_created.emit()

            except Exception as error:
                shutil.rmtree(
                    instance_directory, ignore_errors=True
                )
                bus.show_error.emit(
                    tr("title_modpack_error"), str(error)
                )
            finally:
                bus.modpack_done.emit()

        threading.Thread(target=worker, daemon=True).start()


